// Generated by afz-rust: the driver entry, rendered verbatim into the driver crate.
//
// One invocation per process: read the request JSON on stdin, catch the panic, dump the
// coverage buffer, and answer with exactly one JSON line on stdout. Target code is free to
// shout at this process's stdout after us; the harness reads only the one line we print, and
// the protocol channel that matters is the harness's own, a different process.
mod afzrt;
mod calls;

use std::io::{Read as _, Write as _};
use std::sync::Mutex;

extern "C" {
    fn __llvm_profile_get_size_for_buffer() -> usize;
    fn __llvm_profile_write_buffer(buffer: *mut u8) -> i32;
}

/// The panic hook records `message\x1flocation` here; `main` reads it after `catch_unwind`
/// returns, because the payload itself is only reachable through the hook's `PanicHookInfo`.
static PANIC: Mutex<Option<String>> = Mutex::new(None);

fn main() {
    std::panic::set_hook(Box::new(|info| {
        let message = info
            .payload()
            .downcast_ref::<String>()
            .cloned()
            .or_else(|| info.payload().downcast_ref::<&str>().map(|s| s.to_string()))
            .unwrap_or_else(|| "panic".to_string());
        let location = info.location().map(|l| format!("{}:{}", l.file(), l.line())).unwrap_or_default();
        let _ = PANIC.lock().map(|mut slot| *slot = Some(format!("{message}\u{1f}{location}")));
    }));
    let mut input = String::new();
    let _ = std::io::stdin().read_to_string(&mut input);
    let response = match serde_json::from_str::<serde_json::Value>(&input) {
        Ok(request) => {
            let name = request.get("call").and_then(|c| c.as_str()).unwrap_or("");
            let empty: Vec<serde_json::Value> = Vec::new();
            let args = request.get("args").and_then(|a| a.as_array()).unwrap_or(&empty);
            match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| calls::dispatch(name, args))) {
                Ok(Ok(answer)) => answer,
                Ok(Err(message)) => serde_json::json!({"status": "error", "message": message}),
                Err(_) => match PANIC.lock().ok().and_then(|slot| slot.clone()) {
                    Some(joined) => {
                        let (message, location) = joined.split_once('\u{1f}').unwrap_or((joined.as_str(), ""));
                        let (file, line) = location.rsplit_once(':').unwrap_or((location, "0"));
                        serde_json::json!({
                            "status": "panicked",
                            "message": message,
                            "file": file,
                            "line": line.parse::<u32>().unwrap_or(0),
                        })
                    }
                    None => serde_json::json!({"status": "panicked", "message": "panic", "file": "", "line": 0}),
                },
            }
        }
        Err(e) => serde_json::json!({"status": "error", "message": format!("the request is not valid JSON: {e}")}),
    };
    dump_profile();
    let mut stdout = std::io::stdout();
    let _ = writeln!(stdout, "{response}");
    let _ = stdout.flush();
}

/// Write the LLVM instrumentation runtime's buffer to `AFZ_DRIVER_PROFRAW`. The symbols only
/// exist because the harness builds this crate with `-Cinstrument-coverage`.
fn dump_profile() {
    let path = std::env::var("AFZ_DRIVER_PROFRAW").unwrap_or_default();
    if path.is_empty() {
        return;
    }
    let size = unsafe { __llvm_profile_get_size_for_buffer() };
    let mut buffer = vec![0u8; size];
    let code = unsafe { __llvm_profile_write_buffer(buffer.as_mut_ptr()) };
    if code == 0 {
        let _ = std::fs::write(path, buffer);
    }
}
